// Normalises whatever a buyer's agent sends, then emits one item per package
// so the HTTP node downstream fans out over them.
//
// There is no single shape to expect. The same request, phrased the same way by
// the same model, arrives as a top-level name and version, as a list of
// objects, as a package.json map, or as "lodash@4.17.20". A paid worker is a
// public API with no docs and no support channel, so being liberal here is the
// job, not sloppiness.

const body = $input.first().json.body || {};
const input = body.input ?? body ?? {};

const ver = (v) => String(v).replace(/^[\^~>=<\s]+/, '').replace(/\s.*$/, '').trim();

function one(entry, key) {
  if (entry == null) return null;
  if (typeof entry === 'string') {
    if (key) return { name: key, version: ver(entry) };
    const m = entry.trim().match(/^(@?[\w./-]+?)[@\s]+v?([\d][\w.+-]*)$/);
    return m ? { name: m[1], version: m[2] } : { name: entry.trim(), version: 'latest' };
  }
  if (typeof entry === 'object') {
    const name = entry.name || entry.package || entry.id || key;
    if (!name) return null;
    return { name: String(name), version: ver(entry.version || entry.range || entry.v || 'latest') };
  }
  return null;
}

function collect(v) {
  if (!v) return [];
  if (Array.isArray(v)) return v.map((e) => one(e, null));
  if (typeof v === 'object') return Object.entries(v).map(([k, e]) => one(e, k));
  if (typeof v === 'string') return [one(v, null)];
  return [];
}

let pkgs = [];
if (input.packages !== undefined) pkgs = collect(input.packages);
else if (input.dependencies !== undefined) pkgs = collect(input.dependencies);
else if (input.deps !== undefined) pkgs = collect(input.deps);
else if (Array.isArray(input)) pkgs = collect(input);
else if (input.name || input.package) pkgs = [one(input, null)];
else if (typeof input === 'string') pkgs = collect(input);

pkgs = pkgs
  .filter((p) => p && p.name && !/^\d+$/.test(p.name))
  .map((p) => ({ name: String(p.name), version: String(p.version || 'latest') }))
  .slice(0, 25);

if (!pkgs.length) {
  throw new Error(
    'No packages found. Accepted: {"input":{"name":"lodash","version":"4.17.20"}}, ' +
    '{"input":{"dependencies":[{"name","version"}]}}, ' +
    '{"input":{"dependencies":{"lodash":"^4.17.20"}}}, ' +
    '{"input":{"packages":["lodash@4.17.20"]}}. ' +
    'Received: ' + JSON.stringify(input).slice(0, 250)
  );
}

// npm's own search index carries the publish date and its quality, popularity
// and maintenance scores in one small response. The full packument has the same
// dates but is megabytes for a popular package, which is a bad trade for a
// worker that has to answer inside a request.
return pkgs.map((p) => ({ json: {
  name: p.name,
  version: p.version,
  url: 'https://registry.npmjs.org/-/v1/search?size=1&text=' + encodeURIComponent(p.name),
} }));

const asked = $('Read the request').all().map((i) => i.json);
const got = $input.all().map((i) => i.json);

if (got.length !== asked.length) {
  throw new Error(
    'The registry answered for ' + got.length + ' of ' + asked.length + ' packages. ' +
    'Refusing to report a partial audit as a complete one.'
  );
}

const DAY = 24 * 60 * 60 * 1000;
const now = Date.now();

const results = asked.map((a, i) => {
  const hit = ((got[i] || {}).objects || [])[0] || null;
  const pkg = hit ? hit.package || {} : {};

  // The search index is fuzzy: it will happily return a near-miss for a name
  // that does not exist. Matching exactly is the difference between "this
  // package is fine" and "some other package is fine".
  const matched = pkg.name && String(pkg.name).toLowerCase() === a.name.toLowerCase();
  if (!matched) {
    return {
      package: a.name,
      status: 'not-found',
      detail: 'No package by this exact name on the npm registry.',
    };
  }

  const published = pkg.date ? Date.parse(pkg.date) : NaN;
  const ageDays = Number.isFinite(published) ? Math.floor((now - published) / DAY) : null;
  const score = hit.score || {};
  const d = score.detail || {};

  const signals = [];
  if (ageDays !== null && ageDays > 730) signals.push('No release in over two years.');
  if (ageDays !== null && ageDays > 365 && ageDays <= 730) signals.push('No release in over a year.');
  if (typeof d.maintenance === 'number' && d.maintenance < 0.3) signals.push('npm maintenance score is low.');
  if ((pkg.maintainers || []).length === 1) signals.push('Single maintainer: one person is the bus factor.');
  if (a.version !== 'latest' && pkg.version && a.version !== pkg.version) {
    signals.push('You are on ' + a.version + '; latest is ' + pkg.version + '.');
  }

  return {
    package: a.name,
    yourVersion: a.version,
    latestVersion: pkg.version || null,
    lastPublished: pkg.date || null,
    daysSinceRelease: ageDays,
    maintainers: (pkg.maintainers || []).length || null,
    scores: {
      quality: typeof d.quality === 'number' ? Math.round(d.quality * 100) / 100 : null,
      popularity: typeof d.popularity === 'number' ? Math.round(d.popularity * 100) / 100 : null,
      maintenance: typeof d.maintenance === 'number' ? Math.round(d.maintenance * 100) / 100 : null,
    },
    status: signals.length ? 'attention' : 'healthy',
    signals,
    links: pkg.links || null,
  };
});

const attention = results.filter((r) => r.status === 'attention');
const missing = results.filter((r) => r.status === 'not-found');

return [{ json: { output: {
  scanned: results.length,
  needsAttention: attention.length,
  notFound: missing.length,
  verdict: attention.length === 0 && missing.length === 0
    ? 'Every dependency is actively maintained and current.'
    : attention.length + ' of ' + results.length + ' dependencies show maintenance risk.',
  packages: results,
  source: 'registry.npmjs.org search index',
  note: 'Maintenance signals, not a security scan. Pair with an advisory lookup.',
  checkedAt: new Date().toISOString(),
} } }];
